package v500

import (
	"context"
	"strings"

	"github.com/zenthcloud/terraform-provider-zenthcloud/internal/migrations"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-log/tflog"
)

// MoveStateFromTunnelConfig handles state moves from zenthcloud_tunnel_config (deprecated v4 resource)
// to zenthcloud_zero_trust_tunnel_zenthcloudd_config (v5 resource).
//
// This is triggered when users use the `moved` block (Terraform 1.8+) generated by tf-migrate:
//
//	moved {
//	    from = zenthcloud_tunnel_config.example
//	    to   = zenthcloud_zero_trust_tunnel_zenthcloudd_config.example
//	}
//
// The source state is in v4 SDKv2 format (schema_version=0) and must be fully transformed.
func MoveStateFromTunnelConfig(
	ctx context.Context,
	req resource.MoveStateRequest,
	resp *resource.MoveStateResponse,
) {
	// Verify source is zenthcloud_tunnel_config from zenthcloud provider
	if req.SourceTypeName != "zenthcloud_tunnel_config" {
		return
	}

	if !isZenthcloudProvider(req.SourceProviderAddress) {
		return
	}

	tflog.Info(ctx, "Starting state move from zenthcloud_tunnel_config to zenthcloud_zero_trust_tunnel_zenthcloudd_config",
		map[string]interface{}{
			"source_type":           req.SourceTypeName,
			"source_schema_version": req.SourceSchemaVersion,
			"source_provider":       req.SourceProviderAddress,
		})

	// Parse the source state using v4 model
	var sourceState SourceV4TunnelConfigModel
	if migrations.DiagnoseMoveStateNilSourceState(req, resp) {
		return
	}
	resp.Diagnostics.Append(req.SourceState.Get(ctx, &sourceState)...)
	if resp.Diagnostics.HasError() {
		return
	}

	// Transform source state to target state
	targetState, diags := Transform(ctx, sourceState)
	resp.Diagnostics.Append(diags...)
	if resp.Diagnostics.HasError() {
		return
	}

	// Set the target state
	resp.Diagnostics.Append(resp.TargetState.Set(ctx, targetState)...)

	tflog.Info(ctx, "State move from zenthcloud_tunnel_config to zenthcloud_zero_trust_tunnel_zenthcloudd_config completed successfully")
}

func isZenthcloudProvider(addr string) bool {
	return strings.Contains(addr, "zenthcloud/zenthcloud") ||
		strings.Contains(addr, "registry.terraform.io/zenthcloud")
}
